import ProductCard from "../components/ProductCard";

function Productos() {
  return (
    <div>
      <h2>Catálogo de Productos</h2>

      <div className="contenedor">
        <ProductCard nombre="Arroz" precio="4.00" />
        <ProductCard nombre="Aceite" precio="11.00" />
        <ProductCard nombre="Azúcar" precio="4.50" />
      </div>
    </div>
  );
}

export default Productos;
